insert into public.intake_forms (key, program_id, title, introduction, questions, result_rules, version, is_published)
values ('goal-setting', null, 'Set your goal',
  'A few questions so we can point you at the right plan. You can change your answers any time.', '[{"id":"goal","eyebrow":"Step 01","title":"What do you want most right now?","questions":[{"id":"goal_kind","label":"Choose your main goal","type":"single","required":true,"options":[{"value":"strength","label":"Get stronger","description":"Build real strength with the big kettlebell lifts."},{"value":"technique","label":"Sharpen my technique","description":"Cleaner swings, cleans, snatches and presses."},{"value":"mobility","label":"Move better","description":"Mobility, flexibility and joints that feel good."},{"value":"conditioning","label":"Build conditioning","description":"Engine, work capacity and fat loss."},{"value":"mindset","label":"Mindset and calm","description":"Breath, presence and handling stress."},{"value":"retreat_prep","label":"Prepare for a retreat","description":"Get body and mind ready for Men of Movement."}]},{"id":"target_date","label":"Is there a date you are working towards?","help":"Optional — a retreat, an event, a birthday.","type":"date"}]},{"id":"programs","eyebrow":"Step 02","title":"Which programs interest you?","questions":[{"id":"programs","label":"Programs you want in your plan","help":"Select all that apply. Leave empty and we will choose.","type":"multi","options":[]}]},{"id":"approach","eyebrow":"Step 03","title":"How do you want to be guided?","questions":[{"id":"approach","label":"Choose an approach","type":"single","required":true,"options":[{"value":"guided","label":"Guide me","description":"Start from one of Mike''s plans and follow it."},{"value":"custom","label":"Build it with me","description":"Shape your own plan from the lessons you choose."}]}]},{"id":"schedule","eyebrow":"Step 04","title":"Your week","questions":[{"id":"days_per_week","label":"How many days a week can you train?","type":"single","required":true,"options":[{"value":"2","label":"2"},{"value":"3","label":"3"},{"value":"4","label":"4"},{"value":"5","label":"5"}]},{"id":"session_length","label":"How long is a typical session?","type":"single","options":[{"value":"15","label":"About 15 minutes"},{"value":"30","label":"About 30 minutes"},{"value":"45","label":"About 45 minutes"},{"value":"60","label":"An hour or more"}]}]},{"id":"setup","eyebrow":"Step 05","title":"Your setup","questions":[{"id":"equipment","label":"What equipment do you have?","help":"Select all that apply.","type":"multi","options":[{"value":"One kettlebell","label":"One kettlebell"},{"value":"Two kettlebells (a pair)","label":"Two kettlebells (a pair)"},{"value":"Several kettlebells","label":"Several kettlebells"},{"value":"Pull-up bar","label":"Pull-up bar"},{"value":"Mat and floor space","label":"Mat and floor space"},{"value":"Full gym","label":"Full gym"}]},{"id":"injuries","label":"Any injuries or limits we should know about?","help":"Optional.","type":"text"}]}]'::jsonb, '{"kind":"goal","goal_q":"goal_kind","target_q":"target_date","programs_q":"programs","approach_q":"approach","titles":{"strength":"Get stronger","technique":"Sharpen my technique","mobility":"Move better","conditioning":"Build conditioning","mindset":"Mindset and calm","retreat_prep":"Prepare for a retreat"}}'::jsonb, 1, true)
on conflict (key) do update set title = excluded.title, introduction = excluded.introduction, questions = excluded.questions,
  result_rules = excluded.result_rules, is_published = true, updated_at = now();
-- programs of interest = published training programs (value = slug)
update public.intake_forms set questions = jsonb_set(questions, '{1,questions,0,options}', coalesce((
  select jsonb_agg(jsonb_build_object('value', p.slug, 'label', p.name, 'description', p.tagline) order by p.position, p.name)
  from public.programs p where p.status = 'published' and p.type in ('day_program', 'course', 'challenge')
    and p.catalog_group in ('training', 'experiences')), '[]'::jsonb))
where key = 'goal-setting';

insert into public.intake_forms (key, program_id, title, introduction, questions, result_rules, version, is_published)
select 'kbl-intake', p.id, 'Kettlebell Lifestyle intake',
  'Thirteen quick steps so we can drop you into the right level of Kettlebell Lifestyle.', '[{"id":"experience","eyebrow":"Step 01","title":"Your kettlebell history","intro":"We start with the basics so we can drop you into the right level of Kettlebell Lifestyle.","questions":[{"id":"used_kettlebell","label":"Have you ever used a kettlebell before?","type":"single","required":true,"options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]}]},{"id":"level","eyebrow":"Step 02","title":"Describe your kettlebell level","intro":"Not sure? Use the intermediate movement standards as your guide — squats, two hand swings, deadlifts and overhead presses should feel proficient, not new.","questions":[{"id":"kettlebell_level","label":"Describe your kettlebell level","type":"single","required":true,"options":[{"value":"beginner","label":"Beginner","bullets":["I’ve rarely used a kettlebell before"]},{"value":"intermediate","label":"Intermediate","bullets":["I use a kettlebell fairly often","I feel proficient with squats, two hand swings, deadlifts and overhead presses"]},{"value":"advanced","label":"Advanced"}]}]},{"id":"fitness","eyebrow":"Step 03","title":"Fitness baseline","questions":[{"id":"fitness_level","label":"Describe your fitness level","type":"single","options":[{"value":"low","label":"Low","bullets":["I feel out of shape"]},{"value":"medium","label":"Medium","bullets":["I’m in decent shape, and/or I train with resistance at least 2x/week"]},{"value":"high","label":"High","bullets":["My fitness is on the higher side, and/or I train with resistance 3+ times a week"]}]},{"id":"consistency","label":"How long have you been consistently exercising?","type":"single","options":[{"value":"lt6m","label":"Less than 6 months"},{"value":"6m-2y","label":"Between 6 months and 2 years"},{"value":"gt2y","label":"More than 2 years"}]}]},{"id":"mobility","eyebrow":"Step 04","title":"Joint mobility","intro":"This tells us how much prep and mobility work to weave into your on-ramp.","questions":[{"id":"shoulders","label":"Do your shoulder(s) feel limited or restricted in some way?","type":"single","options":[{"value":"no","label":"No"},{"value":"some","label":"Yes, but not much"},{"value":"lots","label":"Yes, quite a bit"}]},{"id":"hips","label":"Do your hip(s) feel limited or restricted in some way?","type":"single","options":[{"value":"no","label":"No"},{"value":"some","label":"Yes, but not much"},{"value":"lots","label":"Yes, quite a bit"}]}]},{"id":"goals","eyebrow":"Step 05","title":"What do you want to improve most?","questions":[{"id":"focus_areas","label":"What areas of your training, ability, or lifestyle do you wish to improve upon most?","help":"Select all that apply.","type":"multi","options":[{"value":"Kettlebell Skill","label":"Kettlebell Skill"},{"value":"Health","label":"Health"},{"value":"Fitness","label":"Fitness"},{"value":"Longevity & Injury Prevention","label":"Longevity & Injury Prevention"},{"value":"Flexibility/Mobility","label":"Flexibility/Mobility"},{"value":"Mindset","label":"Mindset"},{"value":"Nutrition","label":"Nutrition"},{"value":"Sleep","label":"Sleep"},{"value":"Strength","label":"Strength"},{"value":"Conditioning","label":"Conditioning"},{"value":"Fat Loss","label":"Fat Loss"}]}]},{"id":"hydration","eyebrow":"Step 06","title":"Hydration","questions":[{"id":"water","label":"Are you drinking at least half an ounce of quality filtered water per pound of bodyweight a day?","type":"single","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]}]},{"id":"sleep","eyebrow":"Step 07","title":"Sleep","note":{"title":"Questions to consider on sleep quality","points":["Do you fall asleep easily (~30 minutes or less)?","Are you waking up multiple times a night?","Do you wake up in the morning feeling rested?"]},"questions":[{"id":"sleep","label":"Do you get 7+ hours of quality sleep per night?","type":"single","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]}]},{"id":"nutrition","eyebrow":"Step 08","title":"Nutrition & digestion","questions":[{"id":"nutrition","label":"How would you describe your nutrition and digestion?","type":"single","options":[{"value":"above","label":"Above average","bullets":["Food leaves me energised, with regular, easy to pass bowel movements"]},{"value":"average","label":"Average","bullets":["I generally eat clean, but certain foods affect my digestion adversely"]},{"value":"below","label":"Below average","bullets":["I don’t eat the greatest, and/or often experience digestive discomfort"]}]}]},{"id":"stress","eyebrow":"Step 09","title":"Stress & balance","questions":[{"id":"stress_level","label":"How would you describe your daily stress level?","type":"single","options":[{"value":"low","label":"Low","bullets":["I rarely feel stressed"]},{"value":"moderate","label":"Moderate","bullets":["I’m sometimes stressed, but I manage it well"]},{"value":"high","label":"High","bullets":["I feel stressed a majority of the time"]}]},{"id":"stress_management","label":"How well do you manage your stress on a daily basis?","type":"single","options":[{"value":"poorly","label":"Poorly"},{"value":"moderate","label":"Moderate"},{"value":"well","label":"Well"}]},{"id":"work_life","label":"Do you feel you have a good work-life balance?","type":"single","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]}]},{"id":"solitude","eyebrow":"Step 10","title":"Time with yourself","questions":[{"id":"alone","label":"How comfortable do you feel being alone?","type":"single","options":[{"value":"uncertain","label":"Not very / uncertain","bullets":["I’ve never paid attention to this and am not sure"]},{"value":"mild","label":"Mildly","bullets":["I don’t feel comfortable unless I’m around others, or have the TV or radio on"]},{"value":"super","label":"Super comfortable","bullets":["I can sit quietly or meditate with no distractions for an hour"]}]}]},{"id":"flexibility","eyebrow":"Step 11","title":"Flexibility","questions":[{"id":"flexibility","label":"Would you consider your body to be:","type":"single","options":[{"value":"stiff","label":"Stiff as a board and not flexible"},{"value":"mild","label":"Mildly flexible"},{"value":"high","label":"Highly flexible"}]}]},{"id":"posture","eyebrow":"Step 12","title":"Posture","note":{"title":"Not sure?","points":["If your posture shows characteristics of anything other than good posture, choose option 1 or 2.","One tell: where do your ears sit relative to your shoulders when standing relaxed?"]},"questions":[{"id":"posture","label":"Do you feel your posture is:","type":"single","options":[{"value":"poor","label":"Poor and out of balance"},{"value":"ok","label":"Ok, but could use some improvement"},{"value":"good","label":"Good and well-balanced"}]}]},{"id":"coordination","eyebrow":"Step 13","title":"Coordination","questions":[{"id":"coordination","label":"How would you describe your level of coordination?","type":"single","options":[{"value":"low","label":"Low","description":"I feel like a baby giraffe at times ; )"},{"value":"medium","label":"Medium","description":"Somewhere between a giraffe and a cheetah"},{"value":"high","label":"High","description":"Oh heck yeah, I’m a cheetah!"}]}]}]'::jsonb, '{"kind":"first_match","rules":[{"when":{"all":[{"q":"used_kettlebell","eq":"yes"},{"q":"kettlebell_level","in":["intermediate","advanced"]},{"q":"fitness_level","neq":"low"}]},"result":{"path_key":"intermediate","label":"Level II — Intermediate","headline":"You’re starting at Level II","summary":"Your kettlebell background and training consistency mean you can skip the absolute basics and start with the Intermediate track."}}],"default":{"path_key":"beginner","label":"Level I — Beginner","headline":"You’re starting at Level I","summary":"We’ll build your foundation first: the On Ramp phase teaches the positions and breathing that everything else is stacked on."},"notes":[{"when":{"any":[{"q":"shoulders","eq":"lots"},{"q":"hips","eq":"lots"}]},"text":"Prioritise the mobility work in the On Ramp — your joints need runway before load."},{"when":{"q":"flexibility","eq":"stiff"},"text":"Add the stretch protocols after every session and retake the Stretch Test in 4 weeks."},{"when":{"q":"posture","eq":"poor"},"text":"Run the posture correctives daily; they unlock your overhead positions."},{"when":{"q":"sleep","eq":"no"},"text":"Sleep is the cheapest performance gain available — aim for 7+ hours before adding volume."},{"when":{"q":"water","eq":"no"},"text":"Dial in hydration: half an ounce of filtered water per pound of bodyweight, daily."},{"when":{"q":"nutrition","eq":"below"},"text":"Clean up one meal a day before overhauling everything — digestion drives recovery."},{"when":{"any":[{"q":"stress_level","eq":"high"},{"q":"stress_management","eq":"poorly"}]},"text":"Use the breathing and down-regulation lessons on your rest days."},{"when":{"q":"coordination","eq":"low"},"text":"Slow the tempo on skill days — reps at half speed build coordination fastest."}],"notes_default":["You’re in strong shape — focus on technical precision and progressive load."],"notes_limit":4}'::jsonb, 1, true
from public.programs p where p.slug = 'kettlebell-lifestyle'
on conflict (key) do update set program_id = excluded.program_id, title = excluded.title, introduction = excluded.introduction,
  questions = excluded.questions, result_rules = excluded.result_rules, is_published = true, updated_at = now();

