insert into public.intake_forms (key, program_id, title, introduction, questions, result_rules, version, is_published)
select 'mtk-intake', p.id, 'Mastering the Kettlebell assessment',
  'Tell us where your lifts are today and we will recommend where to start in Mastering the Kettlebell.', '[{"id":"about","eyebrow":"Step 01","title":"About you","questions":[{"id":"role","label":"Which best describes you?","type":"single","required":true,"options":[{"value":"Training for myself","label":"Training for myself"},{"value":"Athlete","label":"Athlete"},{"value":"Personal trainer / strength coach","label":"Personal trainer / strength coach"},{"value":"Movement / rehab professional","label":"Movement / rehab professional"},{"value":"I train myself and coach others","label":"I train myself and coach others"}]},{"id":"experience","label":"How much kettlebell experience do you have?","type":"single","required":true,"options":[{"value":"Completely new","label":"Completely new"},{"value":"Used kettlebells a few times","label":"Used kettlebells a few times"},{"value":"Less than 1 year","label":"Less than 1 year"},{"value":"1–3 years","label":"1–3 years"},{"value":"More than 3 years","label":"More than 3 years"},{"value":"I regularly coach kettlebells","label":"I regularly coach kettlebells"}]}]},{"id":"movements","eyebrow":"Step 02","title":"Where your movements are today","questions":[{"id":"confident","label":"Which movements do you already feel confident with?","help":"Select all that apply.","type":"multi","options":[{"value":"Deadlift","label":"Deadlift"},{"value":"Single-Leg Deadlift","label":"Single-Leg Deadlift"},{"value":"Swing","label":"Swing"},{"value":"Clean","label":"Clean"},{"value":"Snatch","label":"Snatch"},{"value":"Press","label":"Press"},{"value":"Jerk","label":"Jerk"},{"value":"Turkish Get Up","label":"Turkish Get Up"},{"value":"Windmill","label":"Windmill"},{"value":"Squat","label":"Squat"},{"value":"Lunge","label":"Lunge"},{"value":"Row","label":"Row"},{"value":"Still learning fundamentals","label":"Still learning fundamentals"},{"value":"Unsure about my technique","label":"Unsure about my technique"}]},{"id":"struggle","label":"Which movements do you struggle with most?","help":"Select all that apply.","type":"multi","options":[{"value":"Deadlift","label":"Deadlift"},{"value":"Single-Leg Deadlift","label":"Single-Leg Deadlift"},{"value":"Swing","label":"Swing"},{"value":"Clean","label":"Clean"},{"value":"Snatch","label":"Snatch"},{"value":"Press","label":"Press"},{"value":"Jerk","label":"Jerk"},{"value":"Turkish Get Up","label":"Turkish Get Up"},{"value":"Windmill","label":"Windmill"},{"value":"Squat","label":"Squat"},{"value":"Lunge","label":"Lunge"},{"value":"Row","label":"Row"},{"value":"None in particular","label":"None in particular"}]}]},{"id":"goals","eyebrow":"Step 03","title":"What you want from MTK","questions":[{"id":"improve","label":"What do you most want to improve?","type":"single","required":true,"options":[{"value":"Strong kettlebell fundamentals","label":"Strong kettlebell fundamentals"},{"value":"Swing / Clean / Snatch","label":"Swing / Clean / Snatch"},{"value":"Power and conditioning","label":"Power and conditioning"},{"value":"Overhead strength and technique","label":"Overhead strength and technique"},{"value":"Turkish Get Up / overhead control","label":"Turkish Get Up / overhead control"},{"value":"Squat / Lunge / Row","label":"Squat / Lunge / Row"},{"value":"Overall strength and movement quality","label":"Overall strength and movement quality"},{"value":"Become a better kettlebell coach","label":"Become a better kettlebell coach"},{"value":"Learn the full system","label":"Learn the full system"}]},{"id":"focus","label":"Which movement area do you want to work on first?","type":"single","required":true,"options":[{"value":"Ballistic Movements","label":"Ballistic Movements"},{"value":"Overhead Movements","label":"Overhead Movements"},{"value":"Lower Body & Pulling","label":"Lower Body & Pulling"},{"value":"All of them","label":"All of them"},{"value":"Not sure","label":"Not sure"}]},{"id":"challenge","label":"What is your biggest challenge right now?","type":"single","options":[{"value":"Technique","label":"Technique"},{"value":"Power/explosiveness","label":"Power/explosiveness"},{"value":"Conditioning","label":"Conditioning"},{"value":"Stability/control","label":"Stability/control"},{"value":"Strength","label":"Strength"},{"value":"Mobility","label":"Mobility"},{"value":"Programming for myself","label":"Programming for myself"},{"value":"Programming for clients","label":"Programming for clients"},{"value":"Complete system understanding","label":"Complete system understanding"},{"value":"Advanced progressions","label":"Advanced progressions"},{"value":"Not sure where to start","label":"Not sure where to start"}]}]},{"id":"practice","eyebrow":"Step 04","title":"Your practice","questions":[{"id":"knowledge","label":"How would you rate your kettlebell knowledge?","type":"single","options":[{"value":"1 — New","label":"1 — New"},{"value":"2 — Developing","label":"2 — Developing"},{"value":"3 — Competent","label":"3 — Competent"},{"value":"4 — Experienced","label":"4 — Experienced"},{"value":"5 — Coach / Advanced","label":"5 — Coach / Advanced"}]},{"id":"time","label":"How much time can you give MTK each week?","type":"single","options":[{"value":"Less than 1 hour","label":"Less than 1 hour"},{"value":"1–2 hours","label":"1–2 hours"},{"value":"2–3 hours","label":"2–3 hours"},{"value":"3–4 hours","label":"3–4 hours"},{"value":"4+ hours","label":"4+ hours"}]},{"id":"guidance","label":"How much guidance do you want?","type":"single","options":[{"value":"Show me exactly where to start","label":"Show me exactly where to start"},{"value":"Recommend a path but let me explore","label":"Recommend a path but let me explore"},{"value":"I already know what I want to work on","label":"I already know what I want to work on"}]}]}]'::jsonb, '{"kind":"score","buckets":["ballistic","overhead","lower","full"],"order":["ballistic","overhead","lower","full"],"rules":[{"when":{"q":"focus","eq":"Ballistic Movements"},"add":{"ballistic":4},"reason":"You chose Ballistic Movements first"},{"when":{"q":"focus","eq":"Overhead Movements"},"add":{"overhead":4},"reason":"You chose Overhead Movements first"},{"when":{"q":"focus","eq":"Lower Body & Pulling"},"add":{"lower":4},"reason":"You chose Lower Body & Pulling first"},{"when":{"q":"focus","eq":"All of them"},"add":{"full":4},"reason":"You chose to work on every area first"},{"when":{"q":"improve","eq":"Swing / Clean / Snatch"},"add":{"ballistic":3},"reason":"Your goal is swing / clean / snatch"},{"when":{"q":"improve","eq":"Power and conditioning"},"add":{"ballistic":3},"reason":"Your goal is power and conditioning"},{"when":{"q":"improve","eq":"Overhead strength and technique"},"add":{"overhead":3},"reason":"Your goal is overhead strength and technique"},{"when":{"q":"improve","eq":"Turkish Get Up / overhead control"},"add":{"overhead":3},"reason":"Your goal is turkish get up / overhead control"},{"when":{"q":"improve","eq":"Squat / Lunge / Row"},"add":{"lower":3},"reason":"Your goal is squat / lunge / row"},{"when":{"q":"improve","eq":"Overall strength and movement quality"},"add":{"lower":3},"reason":"Your goal is overall strength and movement quality"},{"when":{"q":"improve","eq":"Become a better kettlebell coach"},"add":{"full":3},"reason":"Your goal is become a better kettlebell coach"},{"when":{"q":"improve","eq":"Learn the full system"},"add":{"full":3},"reason":"Your goal is learn the full system"},{"when":{"q":"challenge","eq":"Power/explosiveness"},"add":{"ballistic":1}},{"when":{"q":"challenge","eq":"Conditioning"},"add":{"ballistic":1}},{"when":{"q":"challenge","eq":"Stability/control"},"add":{"overhead":1}},{"when":{"q":"challenge","eq":"Strength"},"add":{"lower":1}},{"when":{"q":"challenge","eq":"Mobility"},"add":{"lower":1}},{"when":{"q":"challenge","eq":"Programming for clients"},"add":{"full":1}},{"when":{"q":"challenge","eq":"Complete system understanding"},"add":{"full":1}},{"when":{"q":"challenge","eq":"Advanced progressions"},"add":{"full":1}},{"when":{"q":"confident","has_any":["Deadlift","Swing","Clean","Snatch"]},"add":{"ballistic":1}},{"when":{"q":"confident","has_any":["Press","Jerk","Turkish Get Up","Windmill"]},"add":{"overhead":1}},{"when":{"q":"confident","has_any":["Squat","Lunge","Row"]},"add":{"lower":1}},{"when":{"count":[{"q":"confident","has_any":["Deadlift","Swing","Clean","Snatch"]},{"q":"confident","has_any":["Press","Jerk","Turkish Get Up","Windmill"]},{"q":"confident","has_any":["Squat","Lunge","Row"]}],"gte":3},"add":{"full":2},"reason":"You already work across several movement categories"},{"when":{"any":[{"q":"role","in":["Personal trainer / strength coach","Movement / rehab professional","I train myself and coach others"]},{"q":"experience","eq":"I regularly coach kettlebells"}]},"add":{"full":3},"reason":"You coach others, so the complete system serves you best","suppress_tie_reason":true},{"when":{"any":[{"q":"knowledge","num_gte":5},{"q":"experience","eq":"More than 3 years"}]},"add":{"full":1}}],"none":"ballistic","none_reason":"No single focus stood out, so we start with the ballistic foundation every movement builds on","tie":"full","tie_reason":"No single primary focus stood out","outcomes":{"ballistic":{"path_key":"mtk-ballistic","label":"Ballistic Movements","start_section":4,"initial_focus":["Deadlift / hinge foundation","Swing mechanics","Clean progression"]},"overhead":{"path_key":"mtk-overhead","label":"Overhead Movements","start_section":27,"initial_focus":["Press and jerk pre-check","Overhead press position","Turkish Get Up control"]},"lower":{"path_key":"mtk-lower","label":"Lower Body & Pulling","start_section":37,"initial_focus":["Squat pre-check and pattern","Multi-directional lunges","Row mechanics"]},"full":{"path_key":"mtk-full","label":"Full Mastering the Kettlebell","start_section":2,"initial_focus":["Grips and positions","Deadlift and swing foundations","Work through each movement family in order"]}},"flags":[{"key":"foundation_first","when":{"any":[{"q":"experience","in":["Completely new","Used kettlebells a few times"]},{"q":"confident","has":"Still learning fundamentals"},{"q":"confident","has":"Unsure about my technique"},{"q":"improve","eq":"Strong kettlebell fundamentals"},{"q":"knowledge","num_eq":1}]},"reason":"We''ll start you at the foundations and pre-checks before loading the lifts","override":{"start_section":2,"initial_focus_prefix":["Starting up, grips and positions"],"keep_focus":2}}],"pace":{"q":"time","default":"Aim for 2–3 sessions a week and repeat a section whenever a busy week interrupts you","map":{"Less than 1 hour":"2 short technique sessions a week, one movement at a time","1–2 hours":"2–3 sessions a week, one section per week","2–3 hours":"3 sessions a week, one to two sections per week","3–4 hours":"3–4 sessions a week, two sections per week","4+ hours":"4+ sessions a week, moving through a movement family every 1–2 weeks"}}}'::jsonb, 1, true
from public.programs p where p.slug = 'mastering-the-kettlebell'
on conflict (key) do update set program_id = excluded.program_id, title = excluded.title, introduction = excluded.introduction,
